<?php use Hls\Http\View as V; ?><section class="panel"><p>Nomor tagihan: <strong><?= V::escape($row['bill_ref']) ?></strong></p><p>Supplier: <?= V::escape($row['supplier_name']) ?> · Cabang: <?= V::escape($row['branch_name']) ?></p><p>Tanggal: <?= V::escape($row['bill_date']) ?> · Jatuh tempo: <?= V::escape((string)$row['due_date']) ?> · Status: <?= V::escape($row['status']) ?></p><?php if($row['status']==='DRAFT'&&$access->can('finance.payable.create')): ?><a class="button button-primary" href="<?= $this->url('/finance/payable-edit?id='.(int)$row['id']) ?>">Edit</a><?php endif ?></section><?php if($row['status']==='DRAFT'&&$access->can('finance.payable.post')): ?><form method="post" action="<?= $this->url('/finance/payable-post') ?>" style="display:inline" onsubmit="return confirm('Posting tagihan ini? Setelah diposting, tagihan tidak dapat diedit.');"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary" type="submit">Posting Tagihan</button></form><?php endif ?><section class="panel"><table><thead><tr><th>No.</th><th>Deskripsi</th><th>Kuantitas</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $n=>$i): ?><tr><td><?= $n+1 ?></td><td><?= V::escape($i['description']) ?></td><td><?= V::escape($i['quantity']) ?></td><td><?= \Hls\Http\View::money($i['unit_price']) ?></td><td><?= \Hls\Http\View::money($i['line_total']) ?></td></tr><?php endforeach ?></tbody></table></section><section class="panel"><p>Total tagihan: <?= \Hls\Http\View::money($total) ?></p><p>Total pembayaran: <?= \Hls\Http\View::money($paid) ?></p><p>Sisa utang: <?= \Hls\Http\View::money($remaining) ?></p></section><section class="panel"><h2>Riwayat Pembayaran</h2><?php if(!$payments): ?><p class="empty-state">Belum ada pembayaran.</p><?php else: ?><ul><?php foreach($payments as $p): ?><li><?= V::escape($p['payment_ref']) ?> — <?= \Hls\Http\View::money($p['amount']) ?></li><?php endforeach ?></ul><?php endif ?></section><a class="button" href="<?= $this->url('/finance/payables') ?>">Kembali</a><?php if(in_array($row['status'],['POSTED','PARTIALLY_PAID'],true)&&$remaining>0&&$access->can('finance.payable.pay')): ?><section class="panel"><form method="post" action="<?= $this->url('/finance/payable-pay') ?>" class="form-grid"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Rekening<select name="account_id" required><?php foreach($accounts as $a): ?><option value="<?= (int)$a['id'] ?>"><?= V::escape($a['code'].' - '.$a['name']) ?></option><?php endforeach ?></select></label><label>Tanggal pembayaran<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label>Referensi pembayaran<input name="payment_ref" required></label><label>Nominal<input type="number" name="amount" min="0.01" step="0.01" max="<?= V::escape((string)$remaining) ?>" required></label><label>Keterangan<textarea name="note"></textarea></label><button class="button button-primary" type="submit">Catat Pembayaran</button></form></section><?php endif ?>
